function validate([ransomNote, magazine]) {
  if (typeof ransomNote !== 'string' || ransomNote.length < 1 || ransomNote.length > 100000) return 'ransomNote needs 1 to 100000 letters.';
  if (typeof magazine !== 'string' || magazine.length < 1 || magazine.length > 100000) return 'magazine needs 1 to 100000 letters.';
  if (!/^[a-z]+$/.test(ransomNote) || !/^[a-z]+$/.test(magazine)) return 'Use only lowercase English letters.';
  return null;
}

reference:
function canConstruct(ransomNote, magazine) {
  const counts = new Array(26).fill(0);
  for (const letter of magazine) {
    counts[letter.charCodeAt(0) - 97]++;
  }
  for (const letter of ransomNote) {
    const index = letter.charCodeAt(0) - 97;
    if (counts[index] === 0) {
      return false;
    }
    counts[index]--;
  }
  return true;
}

brute:
function canConstruct(ransomNote, magazine) {
  // Compare the two strings after sorting their letters, walking both with one pointer each.
  const need = [...ransomNote].sort();
  const have = [...magazine].sort();
  let j = 0;
  for (const letter of need) {
    while (j < have.length && have[j] < letter) j++;
    if (j === have.length || have[j] !== letter) return false;
    j++;
  }
  return true;
}

