function generate(rand, size) {
  const word = (length, letters) => Array.from({ length }, () => String.fromCharCode(97 + Math.floor(rand() * letters))).join('');
  const small = size === 'small';
  const letters = small ? 1 + Math.floor(rand() * 4) : 1 + Math.floor(rand() * 26);
  const magazine = word(small ? 1 + Math.floor(rand() * 8) : 5000 + Math.floor(rand() * 5001), letters);
  if (rand() < 0.5) return [word(small ? 1 + Math.floor(rand() * 6) : 1 + Math.floor(rand() * 5000), letters), magazine];
  // Otherwise pick letters out of the magazine, so the note is often buildable; sometimes add one more letter.
  const pool = [...magazine];
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  let note = pool.slice(0, 1 + Math.floor(rand() * pool.length)).join('');
  if (rand() < 0.4) note += word(1, letters);
  return [note, magazine];
}
